INSERT INTO category (id, name, description, language_id) VALUES (1, 'Vocabulary', 'Everyday words and their meaning', (SELECT id FROM language WHERE code = 'en')), (2, 'Grammar', 'Tenses, articles and sentence structure', (SELECT id FROM language WHERE code = 'en')), (3, 'Everyday phrases', 'Useful expressions for daily situations', (SELECT id FROM language WHERE code = 'en'));
INSERT INTO question (id, question_text, difficulty, category_id, created_at) VALUES (1, 'Which word means the opposite of "hot"?', 'EASY', 1, now()), (2, 'What do you call the meal you eat in the morning?', 'EASY', 1, now()), (3, 'Which word is a synonym of "quick"?', 'MEDIUM', 1, now()), (4, 'Which word means "to make something better"?', 'HARD', 1, now()), (5, 'Complete: "She ___ a teacher."', 'EASY', 2, now()), (6, 'Complete: "They ___ to the cinema yesterday."', 'MEDIUM', 2, now()), (7, 'Complete: "If I ___ rich, I would travel the world."', 'HARD', 2, now()), (8, 'How do you greet someone in the morning?', 'EASY', 3, now()), (9, 'What do you say when you did not hear what someone said?', 'MEDIUM', 3, now()), (10, 'What does "It is raining cats and dogs" mean?', 'HARD', 3, now());
